// ========================================================================
// Performance Cache Tests
// ========================================================================

#[cfg(feature = "builder")]
#[test]
fn test_content_size_cache_reuses_result() {
    use gpui_design::DesignSystem;

    MiniAppShell::clear_content_size_cache();
    let design = DesignSystem::neutral();

    let first = MiniAppShell::content_size(800.0, 600.0, &design);
    assert!(MiniAppShell::content_size_cache_is_populated());

    // Same window size and design grid unit should return the cached value.
    let second = MiniAppShell::content_size(800.0, 600.0, &design);
    assert_eq!(first, second);

    // A different window size should recompute and update the cache.
    let third = MiniAppShell::content_size(1024.0, 768.0, &design);
    assert_ne!(first, third);
}

#[test]
fn test_build_menus_with_language_basic() {
    let config = MiniAppConfig::new("Menu Test")
        .with_theme(true)
        .with_i18n(true);

    let menus = MiniApp::build_menus_with_language(&config, Language::English);

    // App, View, and Language menus when theme + i18n are enabled.
    assert_eq!(menus.len(), 3);
    assert_eq!(menus[0].name.as_ref(), "Menu Test");
    assert_eq!(menus[1].name.as_ref(), "View");
    assert_eq!(menus[2].name.as_ref(), "Language");

    let no_i18n = MiniApp::build_menus_with_language(
        &MiniAppConfig::new("Menu Test").with_theme(true),
        Language::English,
    );
    assert_eq!(no_i18n.len(), 2);
}
